mapper.select:
SELECT s.owner_id,s.task_id,s.excerpt_id,s.ordinal, NULL AS source_item_id,NULL AS source_version_id,NULL AS source_version_number,NULL AS source_title, NULL AS source_item_owner_id,NULL AS source_version_owner_id,NULL AS actual_source_item_id, NULL AS actual_source_version_id,NULL AS actual_source_version_number,NULL AS actual_source_title,
FROM ai_material_draft_source s
WHERE s.owner_id=#{owner} AND s.excerpt_id=#{excerptId} ORDER BY s.task_id LIMIT #{limit}

SELECT s.owner_id,s.task_id,NULL AS excerpt_id,s.source_item_id,s.source_version_id, s.source_version_number,s.source_title,s.ordinal, source_item.owner_id AS source_item_owner_id,source.owner_id AS source_version_owner_id, source.item_id AS actual_source_item_id,source.id AS actual_source_version_id, source.version_number AS actual_source_version_number,source.title AS actual_source_title,
FROM ai_knowledge_source s
LEFT JOIN knowledge_item source_item ON source_item.owner_id=s.owner_id AND source_item.id=s.source_item_id LEFT JOIN knowledge_version source ON source.owner_id=s.owner_id AND source.item_id=s.source_item_id AND source.id=s.source_version_id WHERE s.owner_id=#{owner} AND s.source_item_id=#{itemId} ORDER BY s.task_id LIMIT #{limit}
